def validate_contract(value: dict[str, Any]) -> dict[str, Any]:
    require(value.get("schema") == SCHEMA, f"schema must be {SCHEMA!r}")
    contract = value.get("contract")
    require(isinstance(contract, dict), "contract must be an object")
    required = {
