	for name, digest := range map[string]string{"revision": e.RevisionDigest, "artifact": e.ArtifactDigest, "rubric": e.RubricDigest, "input": e.InputDigest, "evidence": e.EvidenceDigest} {
		if !validSHA256Identity(digest) {
