			if card.ID == "" || len(card.TurnIDs) == 0 || len(card.TurnIDs) != len(card.TurnSHA256) || len(card.TurnIDs) > 3 || len(card.Triggers) == 0 || len(card.Triggers) > 1 {
				return distillDiscoveryCacheV1{}, fmt.Errorf("invalid discovery candidate")
			}
		}
	}
	return cache, nil
}

