	args, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, prompt)
	if err != nil {
		return nil, err
	}
	reconcilePromptText := reconcilePrompt()
	reconcileArgs, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, reconcilePromptText)
	if err != nil {
		return nil, err
	}
	// Pin the agent model + effort when set, so distill AND reconcile run on the same
	// (cheap) model. Both are no-ops when empty.
	args = injectAgentEffort(injectAgentModel(args, distillOpts.agent, distillOpts.model), distillOpts.agent, distillOpts.effort)
	reconcileArgs = injectAgentEffort(injectAgentModel(reconcileArgs, distillOpts.agent, distillOpts.model), distillOpts.agent, distillOpts.effort)
	threshold := distillOpts.confidenceThreshold
	if threshold <= 0 {
		threshold = defaultFactConfidenceThreshold
	}
	distillOpts.cacheSalt = distillCacheSalt(prompt, reconcilePromptText, threshold, distillOpts)

	sessions := append([]exportSession(nil), manifest.Sources.Sessions.Sessions...)
	// Excluded sessions must never produce new derived facts.
	sessions, err = filterTombstonedSessions(brainDir, sessions)
	if err != nil {
		return nil, err
	}
	if pipeline == distillPipelineCandidates {
		sessions, err = coalesceCandidateDistillSessions(ctx, brainDir, sessions, func(session exportSession) string {
			return resolveDistillBranch(manifest, session)
		}, func(session exportSession) bool {
			return distillSessionSelected(manifest, session, distillOpts)
		})
func newHookSessionEndCommand(opts Options) *cobra.Command {
	return newHookSessionEndCommandWithDistillAndDelta(opts, runDistill, watchShortTermDelta)
}

// newHookSessionEndCommandWithDistill keeps the production hook unchanged while
// allowing the lifecycle wiring to be exercised without an external provider.
func newHookSessionEndCommandWithDistill(opts Options, distill hookDistillRunner) *cobra.Command {
	return newHookSessionEndCommandWithDistillAndDelta(opts, distill, watchShortTermDelta)
}

func newHookSessionEndCommandWithDistillAndDelta(opts Options, distill hookDistillRunner, delta func(context.Context, *cobra.Command, Options, string) (shortTermStats, error)) *cobra.Command {
	var (
		sessionID string
		branch    string
		agent     string
		model     string
		effort    string
		pipeline  string
	)
	cmd := &cobra.Command{
		Use:   "session-end --session <id>",
		Short: "Refresh and distill the just-ended session (spends tokens; silent on env problems)",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if strings.TrimSpace(sessionID) == "" {
				return fmt.Errorf("--session <id> is required")
			}
			normalizedPipeline, err := normalizeDistillPipeline(pipeline)
			if err != nil {
				return err
			}
			if memoryWorkerOrigin() {
				return nil
			}
			target := agentSurfaceTarget(opts, nil)
			repoDir, local, err := resolveLocalTargetRepoDir(cmd.Context(), opts.Runner, target)
			if err != nil || !local {
				return nil // no local repo: silence, never an error
			}
			perRepo := opts
			perRepo.Env.RepoRoot = repoDir
			// Export only changed sessions and publish the short-term overlay so
			// recall and distill can see the just-ended session immediately. The
			// durable coordinator performs the heavier long-term consolidation.
			sub := &cobra.Command{}
			sub.SetContext(cmd.Context())
			sub.SetOut(cmd.ErrOrStderr())
			sub.SetErr(cmd.ErrOrStderr())
			_, deltaErr := delta(cmd.Context(), sub, perRepo, repoDir)
"}

