package cli

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// memory_cmd.go is the administration surface over the durable work
// record: content-free lifecycle hints (`memory notify`, the endpoint
// implemented host adapters call across the external Entire CLI boundary),
// reconciliation against the canonical manifest, a bounded synchronous
// worker, and inspect/retry/cancel verbs. Reconciliation remains the
// correctness authority: losing every hint and job file loses no memory.

func newMemoryCommand(opts Options) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "memory",
		Short: "Inspect and drive the durable conversation-projection work record (hints, jobs, receipts)",
	}
	cmd.AddCommand(newMemoryNotifyCommand(opts))
	cmd.AddCommand(newMemoryStatusCommand(opts))
	cmd.AddCommand(newMemoryReconcileCommand(opts))
	cmd.AddCommand(newMemoryJobsCommand(opts))
	cmd.AddCommand(newMemoryRetryCommand(opts))
	cmd.AddCommand(newMemoryCancelCommand(opts))
	cmd.AddCommand(newMemoryWorkerCommand(opts))
	cmd.AddCommand(newMemoryRepairCommand(opts))
	cmd.AddCommand(newMemoryRebuildCommand(opts))
	cmd.AddCommand(newMemoryMigrateCommand(opts))
	cmd.AddCommand(newMemoryConfigureCommand(opts))
	cmd.AddCommand(newMemoryAbstractCommand(opts))
	return cmd
}

// memoryWorkerLaunch is the best-effort, non-blocking worker launch used by
// notify. Injectable for tests; a launch failure never fails the host.
var memoryWorkerLaunch = func(repoDir string) error {
	return memoryWorkerLaunchAfter(repoDir, 0)
}

var memoryWorkerLaunchAfter = func(repoDir string, delay time.Duration) error {
	exe, err := os.Executable()
	if err != nil {
		return err
	}
	args := []string{"memory", "worker", "--once"}
	if delay > 0 {
		args = append(args, "--delay", delay.String())
	}
	command := exec.Command(exe, args...)
	command.Dir = repoDir
	command.Env = memoryWorkerChildEnvironment(os.Environ(), repoDir)
	command.Stdout = nil
	command.Stderr = nil
	if err := command.Start(); err != nil {
		return err
	}
	// Reap the child instead of releasing the handle. Process.Release() drops
	// the Go-side handle but the process stays this process's child at the OS
	// level, and the Go runtime installs no SIGCHLD reaper, so every launch
	// left a <defunct> entry for the parent's whole lifetime. A long-lived
	// `entire watch` or MCP server launches one worker per tick with changes
	// and accumulated a PID each time, up to RLIMIT_NPROC. Waiting in a
	// goroutine keeps the launch non-blocking and does not tie the child's
	// lifetime to ours: if this process exits first, the child is reparented
	// and keeps running exactly as before.
	go func() { _ = command.Wait() }()
	return nil
}

// memoryAbstractCancellationPollInterval bounds how long a running abstract
// provider can miss a durable cancellation request. It is a variable only so
// race tests can prove cancellation without sleeping for production time.
var memoryAbstractCancellationPollInterval = 5 * time.Second

// memoryWorkerChildEnvironment replaces inherited routing values instead of
// appending duplicates. Workspace/watch processes can be bound to repo A while
// launching a worker for repo B; the child must resolve only B's Brain and work
// queue. Windows environment keys are case-insensitive.
func memoryWorkerChildEnvironment(environ []string, repoDir string) []string {
			// Record the lifecycle event even when export failed. The hint is
			// content-free and durable; startup/watch reconciliation or a later
			// worker pass can repair the missed export without retaining content.
			resolvedBranch := strings.TrimSpace(branch)
			storage, storageErr := repoStoragePaths(cmd.Context(), perRepo.Runner, perRepo.Env, repoDir)
			if storageErr == nil {
				if resolvedBranch == "" {
					if current, gitErr := gitScalar(cmd.Context(), perRepo.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
						resolvedBranch = strings.TrimSpace(current)
					}
				}
				_, warning, hintErr := recordMemoryLifecycleAndLaunch(
					storage.BrainDir, repoDir, storage.Key, sessionID, resolvedBranch, "session_end", perRepo.Now().UTC(),
				)
				if hintErr != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "session-end: memory hint failed: %v\n", hintErr)
				} else if warning != "" {
					fmt.Fprintf(cmd.ErrOrStderr(), "session-end: %s\n", warning)
				}
			}
			// Deterministic, token-free and bounded: index the commits the
			// session just produced so "which checkpoint changed this symbol"
			// is answerable immediately. It runs AFTER the durable lifecycle
			// hint (that must never wait on a slow provider) and independently
			// of the export result, since it reads git, not transcripts. Never
			// fails the hook.
			if entityErr := refreshEntityIndexQuietly(cmd.Context(), perRepo, repoDir); entityErr != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "session-end: entity index refresh skipped: %v\n", entityErr)
			}
			if deltaErr != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "session-end: incremental export failed: %v\n", deltaErr)
				return nil
			}
			distillOpts := distillCommandOptions{
				session:             sessionID,
				agent:               agent,
				model:               model,
				effort:              effort,
				pipeline:            normalizedPipeline,
				branch:              resolvedBranch,
				timeout:             defaultDistillTimeout,
				maxChunkBytes:       defaultDistillChunkSize,
				confidenceThreshold: defaultFactConfidenceThreshold,
			}
			if err := distill(cmd.Context(), sub, opts, distillOpts, repoDir); err != nil {
				// No agent on PATH, session not exported yet, etc.: report on
				// stderr for the curious, succeed for the harness.
				fmt.Fprintf(cmd.ErrOrStderr(), "session-end: distill skipped: %v\n", err)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&sessionID, "session", "", "The just-ended session's id")
	cmd.Flags().StringVar(&branch, "branch", "", "Captured branch when the host knows it")
	cmd.Flags().StringVar(&agent, "agent", "auto", "Distill agent: auto, codex, claude-code, or command")
	cmd.Flags().StringVar(&model, "model", "", "Cheap/fast model override for the distill agent (recommended)")
	cmd.Flags().StringVar(&effort, "effort", "", "Reasoning-effort override (e.g. low) — pairs with --model for a cheap run")
	cmd.Flags().StringVar(&pipeline, "pipeline", distillPipelineLegacy, "Distillation input pipeline: legacy or candidates (experimental)")
	return cmd
}

